package com.hbm.client.soldering;
import com.hbm.machine.centrifuge.OverdriveUpgradeItem;import com.hbm.machine.electricfurnace.FurnaceUpgradeItem;import net.minecraft.ChatFormatting;import net.minecraft.client.Minecraft;import net.minecraft.network.chat.Component;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.entity.player.ItemTooltipEvent;
/** Source IUpgradeInfoProvider labels/formulae, attached only while viewing the real machine. */
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT)
public final class SolderingUpgradeHelp {
 @SubscribeEvent public static void tooltip(ItemTooltipEvent event){if(!(Minecraft.getInstance().screen instanceof SolderingScreen))return;var item=event.getItemStack().getItem();if(item instanceof FurnaceUpgradeItem upgrade){var lines=event.getToolTip();int level=upgrade.tier();lines.add(Component.translatable("container.machineSolderingStation").withStyle(ChatFormatting.YELLOW));if(upgrade.type()==FurnaceUpgradeItem.Type.SPEED){lines.add(Component.translatable("upgrade.delay","-"+(level*100/6)+"%").withStyle(ChatFormatting.GREEN));lines.add(Component.translatable("upgrade.consumption","+"+(level*100)+"%").withStyle(ChatFormatting.RED));}else{lines.add(Component.translatable("upgrade.consumption","-"+(level*100/6)+"%").withStyle(ChatFormatting.GREEN));lines.add(Component.translatable("upgrade.delay","+"+(level*100/3)+"%").withStyle(ChatFormatting.RED));}}else if(item instanceof OverdriveUpgradeItem){event.getToolTip().add(Component.translatable("container.machineSolderingStation").withStyle(ChatFormatting.YELLOW));event.getToolTip().add(Component.translatable("gui.hbm.soldering.yes").withStyle(System.currentTimeMillis()%1000<500?ChatFormatting.RED:ChatFormatting.DARK_GRAY));}}
 private SolderingUpgradeHelp(){}
}
